using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Xml;using MediaPortal.GUI.Library;using MP1SkinStudio.Live;using MP1SkinStudio.LiveBridge;
class NativeProbe{
 static int checks;static readonly List<string> results=new List<string>();
 static FieldInfo F(Type t,string n){for(;t!=null;t=t.BaseType){var f=t.GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.DeclaredOnly);if(f!=null)return f;}throw new Exception(n);}
 static int N(object o,string n){return (int)F(o.GetType(),n).GetValue(o);}static void Set(object o,string n,object v){F(o.GetType(),n).SetValue(o,v);}
 static void Check(bool c,string n){if(!c)throw new Exception(n);checks++;results.Add("PASS "+n);}static void Reject(System.Action a,string n){bool rejected=false;try{a();}catch{rejected=true;}Check(rejected,n);}
 static string[] active={"_itemWidth","_itemHeight","_textureWidth","_textureHeight","_thumbNailWidth","_thumbNailHeight"};static string[] low={"_lowItemWidth","_lowItemHeight","_lowTextureWidth","_lowTextureHeight","_widthThumbNailLow","_heightThumbNailLow"};static string[] big={"_bigItemWidth","_bigItemHeight","_bigTextureWidth","_bigTextureHeight","_widthThumbBig","_heightThumbBig"};
 static void Init(GUIThumbnailPanel g){int[] values={100,80,90,70,60,50};for(int i=0;i<active.Length;i++){Set(g,low[i],values[i]);Set(g,big[i],values[i]*2);Set(g,active[i],values[i]);}}
 [STAThread]static int Main(string[] args){try{Directory.CreateDirectory(args[0]);GUIGraphicsContext.form=new Form{ClientSize=new Size(960,540)};GUIGraphicsContext.form.CreateControl();GUIGraphicsContext.Skin="C:\\Skin";GUIGraphicsContext.SkinSize=new Size(1920,1080);GUIGraphicsContext.OverScanWidth=960;GUIGraphicsContext.OverScanHeight=540;GUIGraphicsContext.Animations=true;
 var check=new GUICheckMarkControl(0);Set(check,"_fontName","");check.FinalizeConstruction();var focused=(GUIAnimation)F(check.GetType(),"_imageCheckMarkFocused").GetValue(check);var off=(GUIAnimation)F(check.GetType(),"_imageCheckMarkNonFocused").GetValue(check);var slots=RuntimeProperty.For(check,"C:\\Skin");
 Set(check,"_selected","#original.flag");var selectedSlot=slots["selected"];var selectedBefore=selectedSlot.Read();selectedSlot.Write(selectedSlot.Parse("yes"));Check(check.Selected&&(string)F(check.GetType(),"_selected").GetValue(check)=="","checkbox preview clears the old native selected expression");selectedSlot.Write(selectedBefore);Check((string)F(check.GetType(),"_selected").GetValue(check)=="#original.flag","checkbox restore retains the original selected binding");Reject(()=>selectedSlot.Parse("maybe"),"invalid checkbox selected value rejected");foreach(string key in new[]{"textureCheckmark","textureCheckmarkNoFocus"}){var slot=slots[key];var native=slot.Read();string before=slot.Value;slot.Write(slot.Parse("temporary.png"));Check(slot.Value=="temporary.png",key+" updates native child texture");slot.Write(native);Check(slot.Value==before,key+" restores original child texture");Reject(()=>slot.Parse("../outside.png"),key+" rejects traversal");Reject(()=>slot.Parse("replacement.xml"),key+" guards animation XML templates");}
 foreach(string key in new[]{"markWidth","markHeight"}){var slot=slots[key];var original=slot.Read();int a=key=="markWidth"?focused.Width:focused.Height,b=key=="markWidth"?off.Width:off.Height;slot.Write(slot.Parse("48"));int expected=key=="markWidth"?GUIGraphicsContext.ScaleHorizontal(48):GUIGraphicsContext.ScaleVertical(48);Check((key=="markWidth"?focused.Width:focused.Height)==expected&&(key=="markWidth"?off.Width:off.Height)==expected,key+" updates both native checkbox images");slot.Write(original);Check((key=="markWidth"?focused.Width:focused.Height)==a&&(key=="markWidth"?off.Width:off.Height)==b,key+" restores both exact native dimensions");}
 var gallery=new GUIThumbnailPanel(0);Init(gallery);slots=RuntimeProperty.For(gallery,"C:\\Skin");string[] keys={"itemWidth","itemHeight","textureWidth","textureHeight","thumbWidth","thumbHeight"};
 for(int mode=0;mode<2;mode++){for(int i=0;i<active.Length;i++)Set(gallery,active[i],N(gallery,mode==0?low[i]:big[i]));for(int i=0;i<keys.Length;i++){string key=keys[i]+(mode==0?"":"Big");var slot=slots[key];var original=slot.Read();int before=N(gallery,active[i]);slot.Write(slot.Parse("150"));int expected=i%2==0?GUIGraphicsContext.ScaleHorizontal(150):GUIGraphicsContext.ScaleVertical(150);Check(N(gallery,active[i])==expected&&N(gallery,mode==0?low[i]:big[i])==expected,key+" updates active layout and stored template");slot.Write(original);Check(N(gallery,active[i])==before,key+" restores exact active dimensions");}}
 Init(gallery);var inactive=slots["thumbWidthBig"];var beforeInactive=inactive.Read();int current=N(gallery,"_thumbNailWidth");inactive.Write(inactive.Parse("170"));Check(N(gallery,"_thumbNailWidth")==current&&N(gallery,"_widthThumbBig")==GUIGraphicsContext.ScaleHorizontal(170),"inactive large thumbnail template does not overwrite the small layout");inactive.Write(beforeInactive);Reject(()=>slots["thumbHeight"].Parse("0"),"zero gallery dimension rejected");
 var items=(List<GUIListItem>)F(gallery.GetType(),"_listItems").GetValue(gallery);items.Add(new GUIListItem("Keep data"));RuntimeProperty.ReflowLayout(gallery);Check(gallery.Count==1&&Object.ReferenceEquals(items,F(gallery.GetType(),"_listItems").GetValue(gallery)),"template updates retain native collection data");
 var label=new GUILabelControl(0);var effects=RuntimeProperty.For(label,"C:\\Skin")["animations"];var originalEffects=label.Animations;var saved=effects.Read();effects.Write(effects.Parse("<effects><animation effect='fade' time='200' start='0' end='100'>VisibleChange</animation></effects>"));Check(label.Animations.Count==2,"VisibleChange creates forward and reverse native effects");effects.Write(saved);Check(Object.ReferenceEquals(label.Animations,originalEffects),"effect restoration retains original native effect objects");Reject(()=>effects.Parse("<!DOCTYPE effects [<!ENTITY x SYSTEM 'file:///invalid'>]><effects>&x;</effects>"),"effect XML rejects DTD");Reject(()=>effects.Parse("<effects><animation effect='fade'>UnknownTrigger</animation></effects>"),"unknown native animation trigger rejected");
 foreach(var c in new GUIControl[]{check,gallery,label})Check(RuntimeProperty.SupportedFields(c.GetType()).SetEquals(RuntimeProperty.For(c,"C:\\Skin").Keys),"supported metadata matches slots for "+c.GetType().Name);
 check.GetID=201;check.Type="checkmark";gallery.GetID=202;gallery.Type="thumbnailpanel";label.GetID=203;label.Type="label";var window=new GUIWindow();Set(window,"_windowLoaded",true);Set(window,"_windowXmlFileName","C:\\Skin\\special.xml");window.Children.Add(check);window.Children.Add(gallery);window.Children.Add(label);var session=new RuntimeSession(()=>window);var snap=session.Handle(LiveWire.Document("snapshot"));var frame=LiveWire.Document("frame");LiveWire.Attr(frame.DocumentElement,"epoch",snap.DocumentElement.GetAttribute("epoch"));foreach(var change in new[]{new[]{"201","markWidth","60"},new[]{"202","thumbWidthBig","180"},new[]{"203","animations","<effects><animation effect='zoom' time='300' start='80' end='100'>WindowOpen</animation></effects>"}}){var node=LiveWire.Add(frame.DocumentElement,"control");LiveWire.Attr(node,"token",snap.SelectSingleNode("/live/control[@id='"+change[0]+"']").Attributes["token"].Value);var value=LiveWire.Add(node,"set");LiveWire.Attr(value,"key",change[1]);value.InnerText=change[2];}int originalMark=focused.Width;session.Handle(frame);Check(focused.Width==GUIGraphicsContext.ScaleHorizontal(60)&&gallery.Count==1&&label.Animations.Count==1,"compound frame applies checkbox, gallery and effects together");var empty=LiveWire.Document("frame");LiveWire.Attr(empty.DocumentElement,"epoch",snap.DocumentElement.GetAttribute("epoch"));session.Handle(empty);Check(focused.Width==originalMark&&gallery.Count==1&&Object.ReferenceEquals(label.Animations,originalEffects),"empty frame restores exact native state and retains data");frame.SelectSingleNode("/live/control/set[@key='thumbWidthBig']").InnerText="0";Reject(()=>session.Handle(frame),"invalid compound frame rejected before native mutation");Check(focused.Width==originalMark&&Object.ReferenceEquals(label.Animations,originalEffects),"rejected frame preserves original native state");session.Reset();Console.WriteLine(checks+" special native checks passed.");return 0;
 }catch(Exception ex){results.Add(ex.ToString());return 1;}finally{Directory.CreateDirectory(args[0]);File.WriteAllLines(Path.Combine(args[0],"Results.txt"),results);foreach(string r in results)Console.WriteLine(r);if(GUIGraphicsContext.form!=null)GUIGraphicsContext.form.Dispose();}}
}
